WITH monthly AS (
  SELECT date_trunc('month', d) AS m, SUM(amount) AS rev
  FROM orders GROUP BY 1
),
ranked AS (
  SELECT m, rev, LAG(rev) OVER (ORDER BY m) AS prev
  FROM monthly
)
SELECT m, rev, (rev - prev) / prev AS mom_growth
FROM ranked;

